from pathlib import Path
from xml.sax.saxutils import escape

root = Path(__file__).resolve().parents[1]
res = root / 'app/src/main/res'
java = root / 'app/src/main/java/com/example/appanh'
def write(path, text):
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.suffix == '.xml':
        from xml.dom import minidom
        text = minidom.parseString(text).toprettyxml(indent='    ')
    path.write_text(text, encoding='utf-8')
def text(value, size=14, extra=''):
    color = '' if 'android:textColor=' in extra else 'android:textColor="?android:attr/textColorPrimary"'
    return f'<TextView android:layout_width="match_parent" android:layout_height="wrap_content" android:text="{escape(value)}" android:textSize="{size}sp" {color} android:paddingVertical="8dp" {extra}/>'
def button(id, value, outline=False):
    style='OutlinedButton' if outline else 'PrimaryButton'
    return f'<com.google.android.material.button.MaterialButton android:id="@+id/{id}" style="@style/{style}" android:layout_width="match_parent" android:layout_height="56dp" android:layout_marginTop="8dp" android:text="{escape(value)}"/>'
def edit(id, hint, kind='text'):
    return f'<com.google.android.material.textfield.TextInputLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_marginTop="14dp" android:hint="{hint}" style="@style/CustomEditText" app:endIconMode="'+('password_toggle' if kind=='textPassword' else 'none')+f'"><com.google.android.material.textfield.TextInputEditText android:id="@+id/{id}" android:layout_width="match_parent" android:layout_height="wrap_content" android:inputType="{kind}" android:maxLines="1"/></com.google.android.material.textfield.TextInputLayout>'
def page(name, title, content, nav=False, dark=False):
    header=f'<com.google.android.material.appbar.MaterialToolbar android:id="@+id/toolbar" android:layout_width="match_parent" android:layout_height="64dp" app:title="{title}" app:titleTextColor="?android:attr/textColorPrimary" app:navigationIcon="@drawable/ic_arrow_back"/>'
    body=f'<LinearLayout android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:orientation="vertical" android:paddingHorizontal="20dp">{content}</LinearLayout>'
    bottom='<com.google.android.material.bottomnavigation.BottomNavigationView android:id="@+id/navigation" android:layout_width="match_parent" android:layout_height="72dp" app:menu="@menu/bottom_navigation_menu" app:labelVisibilityMode="labeled"/>' if nav else ''
    write(res/'layout'/f'{name}.xml',f'<?xml version="1.0" encoding="utf-8"?><LinearLayout xmlns:android="http://schemas.android.com/apk/res/android" xmlns:app="http://schemas.android.com/apk/res-auto" android:id="@+id/screenRoot" android:layout_width="match_parent" android:layout_height="match_parent" android:orientation="vertical" android:background="?android:attr/windowBackground">{header}{body}{bottom}</LinearLayout>')
def scroll(content):
    return f'<androidx.core.widget.NestedScrollView android:layout_width="match_parent" android:layout_height="match_parent" android:fillViewport="true"><LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="vertical" android:paddingBottom="24dp">{content}</LinearLayout></androidx.core.widget.NestedScrollView>'
grid='<androidx.recyclerview.widget.RecyclerView android:id="@+id/grid" android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:clipToPadding="false" android:paddingBottom="16dp"/>'
status=text('Đang tải…',13,'android:id="@+id/status" android:textColor="@color/text_secondary"')
search=edit('search','Tìm kiếm ảnh, video…')
chips='<com.google.android.material.chip.ChipGroup android:layout_width="match_parent" android:layout_height="wrap_content" app:singleSelection="true" app:selectionRequired="true">'+''.join(f'<com.google.android.material.chip.Chip android:id="@+id/{id}" android:layout_width="wrap_content" android:layout_height="wrap_content" android:text="{label}" android:checkable="true" android:checked="{str(i==0).lower()}"/>' for i,(id,label) in enumerate([('all','Tất cả'),('images','Ảnh'),('videos','Video'),('favorites','♥')]))+'</com.google.android.material.chip.ChipGroup>'
logo='<ImageView android:layout_width="88dp" android:layout_height="88dp" android:layout_gravity="center" android:layout_marginTop="30dp" android:src="@drawable/ic_app_logo" android:contentDescription="Biểu tượng Ảnh"/>'
page('activity_splash','',scroll(logo+text('Ảnh',48,'android:gravity="center" android:textStyle="bold"')+text('Lưu giữ khoảnh khắc đẹp',18,'android:gravity="center"')+'<ImageView android:layout_width="match_parent" android:layout_height="220dp" android:src="@drawable/art_landscape" android:contentDescription="Phong cảnh núi và mặt trời"/>'+button('start','Bắt đầu')+button('guest','Khám phá trên thiết bị',True)+text('Khoảnh khắc của bạn. Luôn bên bạn.',12,'android:gravity="center"')))
for register in [False,True]:
    page('activity_register' if register else 'activity_login','Đăng ký' if register else 'Đăng nhập',scroll(logo+text('Tạo tài khoản để bắt đầu' if register else 'Chào mừng bạn quay lại!',24,'android:textStyle="bold"')+text('Cất giữ những điều bạn yêu thương.',14)+(edit('name','Họ và tên') if register else '')+edit('email','Email hoặc số điện thoại (+84…)','textEmailAddress')+edit('password','Mật khẩu (ít nhất 6 ký tự)','textPassword')+button('submit','Đăng ký' if register else 'Đăng nhập')+button('forgot','Quên mật khẩu?',True)+text('Hoặc tiếp tục bằng',13,'android:gravity="center"')+button('google','Tiếp tục với Google',True)+button('switchAuth','Đã có tài khoản? Đăng nhập' if register else 'Chưa có tài khoản? Đăng ký',True)+status))
page('activity_otp','Xác thực tài khoản',scroll(logo+text('Bảo vệ những kỷ niệm của bạn',24,'android:textStyle="bold"')+status+edit('otp','Mã SMS gồm 6 chữ số','number')+button('verify','Xác thực / Tôi đã xác minh email')+button('resend','Gửi lại xác thực',True)))
page('activity_main','Ảnh',search+chips+status+grid+button('importMedia','＋  Thêm ảnh / video'),True)
page('activity_search','Tìm kiếm',search+chips+button('sort','Sắp xếp và bộ lọc',True)+status+grid,True)
for name,title,labels in [
 ('sheet_filter','Bộ lọc',[('newest','Mới nhất'),('oldest','Cũ nhất'),('size','Kích thước lớn nhất'),('type','Tên A → Z')]),
 ('sheet_options','Tùy chọn',[('select','Chọn nhiều'),('addAlbum','Thêm vào album'),('hide','Ẩn ảnh đã chọn / Xem ảnh ẩn'),('settings','Cài đặt'),('help','Trợ giúp')]),
 ('sheet_photo_context','Ảnh của bạn',[('info','Xem chi tiết'),('addAlbum','Thêm vào album'),('favorite','Yêu thích'),('hide','Ẩn / Bỏ ẩn'),('edit','Chỉnh sửa'),('share','Chia sẻ'),('trash','Chuyển vào thùng rác')]),
 ('sheet_share','Chia sẻ ảnh',[('shareFile','Chia sẻ qua ứng dụng'),('shareLink','Chia sẻ liên kết bản sao lưu'),('cancel','Hủy')])]:
    page(name,title,scroll(text('Chọn thao tác',14)+''.join(button(id,label,True) for id,label in labels)))
image='<ImageView android:id="@+id/photo" android:layout_width="match_parent" android:layout_height="0dp" android:layout_weight="1" android:adjustViewBounds="true" android:scaleType="fitCenter" android:contentDescription="Ảnh đang xem"/>'
page('activity_photo_detail','Khoảnh khắc',image+status+button('favorite','♡  Yêu thích',True)+button('edit','Chỉnh sửa',True)+button('share','Chia sẻ',True)+button('more','Thông tin và thao tác',True))
page('activity_edit_photo','Chỉnh sửa',image+text('Lưu thành bản sao • ảnh gốc được giữ lại',12)+ '<LinearLayout android:layout_width="match_parent" android:layout_height="wrap_content" android:orientation="horizontal">'+''.join(f'<Button android:id="@+id/{id}" android:layout_width="0dp" android:layout_weight="1" android:layout_height="48dp" android:text="{label}" android:textSize="11sp"/>' for id,label in [('crop','Cắt 1:1'),('rotate','Xoay'),('filter','Bộ lọc'),('draw','Vẽ')])+'</LinearLayout>'+text('Độ sáng')+'<SeekBar android:id="@+id/brightness" android:layout_width="match_parent" android:layout_height="40dp" android:max="200" android:progress="100"/>'+button('save','Lưu bản sao')+status)
page('dialog_photo_info','Thông tin ảnh',scroll('<ImageView android:id="@+id/photo" android:layout_width="match_parent" android:layout_height="180dp" android:scaleType="centerCrop" android:contentDescription="Ảnh xem trước"/>'+text('',16,'android:id="@+id/details"')+button('close','Đóng')))
page('activity_album','Album',text('Những câu chuyện của bạn',24,'android:textStyle="bold"')+button('createAlbum','＋  Tạo album',True)+status+grid,True)
page('activity_create_album','Tạo album',edit('albumName','Tên album')+text('Chọn ảnh cho câu chuyện mới của bạn')+status+grid+button('create','Tạo album'))
page('activity_album_detail','Album chi tiết',status+grid+button('addPhotos','Thêm ảnh',True)+button('albumOptions','Đổi tên / xóa album',True))
page('activity_trash','Thùng rác',text('Ảnh được giữ 30 ngày. Xóa vĩnh viễn cần xác nhận.',13)+status+grid+button('emptyTrash','Dọn sạch thùng rác'))
page('activity_settings','Cài đặt',scroll(logo+status+''.join(button(id,label,True) for id,label in [('account','Tài khoản'),('backup','Sao lưu và đồng bộ'),('storage','Dung lượng lưu trữ'),('notifications','Thông báo'),('theme','Giao diện'),('language','Ngôn ngữ'),('trash','Thùng rác'),('about','Giới thiệu'),('help','Trợ giúp'),('logout','Đăng xuất')])),True)
page('activity_google_sign_in','Đăng nhập bằng Google',scroll(logo+text('Chọn tài khoản Google',24,'android:gravity="center"')+text('Tài khoản được chọn qua cửa sổ bảo mật của Google.',14)+button('google','Chọn tài khoản')+status))
page('activity_backup','Sao lưu và đồng bộ',scroll(text('Kỷ niệm được cất giữ an toàn',24,'android:textStyle="bold"')+text('File ảnh/video lưu trong Firebase Storage. Thông tin và album lưu trong Cloud Firestore.')+'<com.google.android.material.switchmaterial.SwitchMaterial android:id="@+id/autoBackup" android:layout_width="match_parent" android:layout_height="64dp" android:text="Tự sao lưu khi mở ứng dụng"/><com.google.android.material.switchmaterial.SwitchMaterial android:id="@+id/wifiOnly" android:layout_width="match_parent" android:layout_height="64dp" android:text="Chỉ sao lưu qua Wi-Fi" android:checked="true"/>'+button('backupNow','Sao lưu ngay')+'<ProgressBar android:id="@+id/progress" style="?android:attr/progressBarStyleHorizontal" android:layout_width="match_parent" android:layout_height="20dp" android:max="100"/>'+status))
page('activity_dark_gallery','Ảnh • giao diện tối',search+chips+status+grid+button('importMedia','＋  Thêm ảnh / video'),True)
page('activity_notifications','Thông báo',text('Hoạt động gần đây',24,'android:textStyle="bold"')+status+grid+button('markRead','Đánh dấu tất cả đã đọc',True))
write(res/'layout/item_media.xml','''<com.google.android.material.card.MaterialCardView xmlns:android="http://schemas.android.com/apk/res/android" xmlns:app="http://schemas.android.com/apk/res-auto" android:layout_width="match_parent" android:layout_height="130dp" android:layout_margin="3dp" app:cardCornerRadius="14dp" app:cardElevation="0dp"><FrameLayout android:layout_width="match_parent" android:layout_height="match_parent"><ImageView android:id="@+id/thumbnail" android:layout_width="match_parent" android:layout_height="match_parent" android:scaleType="centerCrop" android:contentDescription="Ảnh trong thư viện"/><TextView android:id="@+id/caption" android:layout_width="match_parent" android:layout_height="wrap_content" android:layout_gravity="bottom" android:background="#99091530" android:textColor="#FFFFFF" android:padding="8dp" android:textSize="12sp"/><TextView android:id="@+id/check" android:layout_width="28dp" android:layout_height="28dp" android:layout_gravity="top|end" android:layout_margin="6dp" android:visibility="gone" android:contentDescription="Đã chọn" android:background="@drawable/bg_selection_number" android:textColor="@color/white" android:textSize="14sp" android:fontFamily="sans-serif-medium" android:gravity="center" android:includeFontPadding="false" android:elevation="2dp"/></FrameLayout></com.google.android.material.card.MaterialCardView>''')
write(res/'drawable/art_landscape.xml','''<vector xmlns:android="http://schemas.android.com/apk/res/android" android:width="360dp" android:height="240dp" android:viewportWidth="360" android:viewportHeight="240"><path android:fillColor="#EAF2FF" android:pathData="M0,0h360v240h-360z"/><path android:fillColor="#FFC76B" android:pathData="M264,48a28,28 0,1 0,1 0z"/><path android:fillColor="#B7D4FF" android:pathData="M0,180L90,55 195,180 265,83 360,177V240H0z"/><path android:fillColor="#75A9F8" android:pathData="M0,210L120,115 222,205 295,151 360,208V240H0z"/><path android:fillColor="#5ECDB4" android:pathData="M0,224Q90,170 180,220Q270,172 360,222V240H0z"/></vector>''')
colors=(res/'values/colors.xml').read_text(encoding='utf-8').replace('#4A90D9','#2864FF').replace('#1A1A2E','#102557').replace('#FFFFFF</color>\n    <color name="background_light"','#F7FAFF</color>\n    <color name="background_light"')
write(res/'values/colors.xml',colors)
print('Generated 21 screen XML layouts and media item.')
